# Convert strings to numeric values
def to_num(string):
    return sum((ord(ch) - ord('a')) * (26 ** (k - i - 1)) for i, ch in enumerate(string))

def to_str(num):
    chars = []
    for _ in range(k):
        num, r = divmod(num, 26)
        chars.append(chr(r + ord('a')))
    return ''.join(reversed(chars))

num_s = to_num(s)
num_t = to_num(t)

# Find the median index in the range [s, t]
total_count = num_t - num_s + 1
median_index = (total_count - 1) // 2

median = num_s + median_index

print(to_str(median))
"}

