import sys
sys.setrecursionlimit(1000000)  # Increase recursion limit for large values

def max_amount(n, memo):
    if n in memo:
        return memo[n]

    # Exchange into three coins and get the sum of their maximum values
    exchange = max_amount(n // 2, memo) + max_amount(n // 3, memo) + max_amount(n // 4, memo)

    # Option to just sell directly
    sell = n

    # Get the maximum value
    result = max(sell, exchange)
    memo[n] = result
    return result

def solve():
    memo = {0: 0}
    for line in sys.stdin:
        n = int(line.strip())
        print(max_amount(n, memo))

if __name__ == "__main__":
    solve()
"}

