def min_insertions(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]

    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if s[i] == s[j]:
                dp[i][j] = dp[i + 1][j - 1]
            else:
                dp[i][j] = min(dp[i + 1][j] + 1, dp[i][j - 1] + 1)

    return dp[0][n - 1]

# Read input
test_cases = int(input())

for _ in range(test_cases):
    n = int(input())
    s = input().strip()
    print(min_insertions(s))
"}

