def solve():
    n = int(input())
    s = input().strip()

    # Check if all blocks are already the same color
    if all(c == 'W' for c in s):
        print(0)
        return
    if all(c == 'B' for c in s):
        print(0)
        return

    # If n is 2 and there are both W and B, impossible
    if n == 2:
        print(-1)
        return

    # For n > 2, we can always make them all the same
    # Let's try to make all W
    ops = []

    # Greedily move W blocks to the left
    for i in range(n):
        if s[i] == 'W':
            # W should be to the left of B
            # If there's a W after a B, we need to fix it
            # We'll flip positions (i, i+1)
            if i < n-1:
                ops.append(i+1)  # 1-indexed
                s = s[:i] + 'B' + s[i+1:]


    # Now all should be W (or we should have failed)
    if all(c == 'W' for c in s):
        print(len(ops))
        print(' '.join(map(str, ops)))
    else:
        # If we failed to make all W, try making all B
        ops_b = []
        for i in range(n):
            if s[i] == 'B':
                if i < n-1:
                    ops_b.append(i+1)
                    s = s[:i] + 'W' + s[i+1:]

        if all(c == 'B' for c in s):
            print(len(ops_b))
            print(' '.join(map(str, ops_b)))
        else:
            print(-1)

solve()
"}

