import sys

def solve():
    t = int(sys.stdin.readline())

    for _ in range(t):
        a, b, c, d = map(int, sys.stdin.readline().split())

        # Pick largest possible x in [a, b] = b
        # Pick largest possible y in [b, c] = c
        # Pick smallest possible z in [c, d] that satisfies triangle inequality

        # x = b, y = c
        # We need to find z such that: c <= z <= d and b + c > z

        # If b + c > c, we can pick z = c
        if b + c > c:
            z = c
        else:
            z = d

        print(f"{b} {c} {z}")

if __name__ == "__main__":
    solve()
"}

