n, m, k = map(int, input().split())

grid = [[0] * m for _ in range(n)]

for _ in range(k):
    op, idx, color = map(int, input().split())
    if op == 1:
        # Paint row idx
        for col in range(m):
            grid[idx - 1][col] = color
    else:
        # Paint column idx
        for row in range(n):
            grid[row][idx - 1] = color

# Print the result
for row in grid:
    print(" ".join(map(str, row)))
"}

