# AtCoder Grand Contest 040 - ><
S = input().strip()
N = len(S) + 1

# Calculate left lengths (increasing subsequence ending at each position)
left_length = [1] * N
for i in range(1, N):
    if S[i-1] == '<':
        left_length[i] = left_length[i-1] + 1
    else:
        left_length[i] = 1

# Calculate right lengths (decreasing subsequence starting at each position)
right_length = [1] * N
for i in range(N-2, -1, -1):
    if S[i] == '>':
        right_length[i] = right_length[i+1] + 1
    else:
        right_length[i] = 1

# Calculate values
value = [0] * N
for i in range(N):
    value[i] = max(left_length[i], right_length[i])

# Output the sum
print(sum(value))
"}

