import sys
from math import gcd
from functools import reduce

def str_to_int(s, base):
    """Convert string s in base `base` to decimal integer."""
    digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    value = 0
    for c in s:
        digit = digits.index(c)
        value = value * base + digit
    return value


def prime_factors(n):
    """Return prime factorization of n as a dictionary: {prime: exponent}"""
    if n == 0 or n == 1:
        return {}
    factors = {}
    for i in range(2, int(n**0.5) + 1):
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n //= i
    if n > 1:
        factors[n] = factors.get(n, 0) + 1
    return factors


def legendre(m, p):
    """Legendre's formula: number of times p divides m!"""
    count = 0
    power = p
    while power <= m:
        count += m // power
        power *= p
    return count


def num_trailing_zeros(m, base):
    """Number of trailing zeros in m! when represented in base `base`"""
    if base == 1:
        return 0

    # Get prime factorization of base
    factors = prime_factors(base)

    # For each prime factor, find how many times it divides m!
    min_count = float('inf')
    for p, exp in factors.items():
        count = legendre(m, p)
        # Number of times p^exp divides m! is floor(count / exp)
        min_count = min(min_count, count // exp)

    return min_count


def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if parts == ['0', '0']:
            break

        n = int(parts[0])
        m_str = parts[1]

        # Convert M from base n to decimal
        m = str_to_int(m_str, n)

        # Compute trailing zeros
        result = num_trailing_zeros(m, n)

        print(result)

if __name__ == '__main__':
    main()
"}

