def solve():
    import sys
    MOD = 10**9 + 7

    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    q = int(next(it))
    a = [int(next(it)) for _ in range(n)]

    # Gaussian elimination to find basis
    def find_basis(arr):
        basis = []
        for num in arr:
            if num == 0:
                continue
            # Eliminate all higher bits
            for i in range(len(basis)):
                if num >> (19 - i) & 1:
                    num ^= basis[i]
            if num != 0:
                basis.append(num)
        return basis

    # Precompute powers of 2 up to n
    power2 = [1] * (n + 1)
    for i in range(1, n + 1):
        power2[i] = (power2[i-1] * 2) % MOD

    # For each query
    output = []
    for _ in range(q):
        l = int(next(it))
        x = int(next(it))

        basis = find_basis(a[:l])

        # Check if x can be formed with the basis
        x_copy = x
        valid = True
        for b in basis:
            if x_copy >> (19 - basis.index(b)) & 1:
                x_copy ^= b
        if x_copy != 0:
            valid = False

        if valid:
            answer = power2[l - len(basis)]
        else:
            answer = 0

        output.append(str(answer % MOD))

    sys.stdout.write("\n".join(output))

if __name__ == "__main__":
    solve()
