import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n, m = int(next(it)), int(next(it))
    c = [int(next(it)) for _ in range(m)]
    colors = [int(next(it)) for _ in range(n)]

    # c is 0-indexed, colors are 1-indexed
    constraints = []
    for j in range(n):
        k = colors[j] - 1  # 0-indexed
        # X should be divisible by c[k] but not by any c[m] for m > k
        divisors = set()
        for i in range(k + 1, m):
            divisors.add(c[i])
        constraints.append((c[k], divisors))

    def backtrack(pos, used, max_val):
        if pos == n:
            return max_val

        min_val = max_val
        if not used:
            min_candidate = 1
        else:
            min_candidate = max(used) + 1

        if pos + 1 < n:
            # Try to use the smallest possible candidate that works
            candidate = min_candidate
            while candidate in used:
                candidate += 1

            k = colors[pos] - 1
            div = constraints[pos][0]
            divisors = constraints[pos][1]

            # Find the smallest candidate that satisfies divisibility
            if candidate % div != 0:
                candidate = candidate + (div - candidate % div)
            if any(candidate % d == 0 for d in divisors):
                # Need to find the next valid number after the first bad one
                candidate = candidate + (1 if any(candidate % d == 0 for d in divisors) else 1)

            result = backtrack(pos + 1, used | {candidate}, candidate)
            if result < min_val:
                min_val = result

        # If we couldn't find a candidate with the same max_val, try larger ones
        for candidate in range(min_candidate, 10**6):
            if candidate in used:
                continue

            k = colors[pos] - 1
            div = constraints[pos][0]
            divisors = constraints[pos][1]

            if candidate % div != 0:
                continue
            if any(candidate % d == 0 for d in divisors):
                continue

            result = backtrack(pos + 1, used | {candidate}, candidate)
            if result < min_val:
                min_val = result

            # Early termination if we find the minimum
            if min_val == candidate and pos + 1 == n:
                break

        return min_val

    result = backtrack(0, set(), 1)
    print(result)

if __name__ == "__main__":
    solve()
