    C = int(data[3])
    lengths = [int(data[4 + i]) for i in range(n)]

    min_mp = float('inf')

    # Try all ways to partition the N bamboos into three non-empty groups
    # We'll use bitmask enumeration
    for mask1 in range(1 << n):
        # First group (target 0)
        group0 = []
        for i in range(n):
            if (mask1 >> i) & 1:
                group0.append(lengths[i])

        if not group0:
            continue

        # Try all ways to select second group from remaining
        for mask2 in range(1 << (n - sum(1 for i in range(n) if (mask1 >> i) & 1))):
            # Actually, we need to iterate over remaining indices
            remaining = [i for i in range(n) if not ((mask1 >> i) & 1)]
            if not remaining:
                continue

            group1 = []
            for i in range(len(remaining)):
                if (mask2 >> i) & 1:
                    group1.append(lengths[remaining[i]])

            if not group1:
                continue

            # Third group is what's left
            group2 = []
            for i in range(len(remaining)):
                if not (mask2 >> i) & 1:
                    group2.append(lengths[remaining[i]])

            # Check we have at least one bamboo in each group
            if not group2:
                continue

            # Compute cost for each subset
            def calc_cost(group, target):
