# Build bipartite graph of possible matchings
from collections import defaultdict

graph = defaultdict(list)

for i, a_i in enumerate(a):
    for j, b_j in enumerate(b):
        if (b_j - a_i) % m == 0:
            # Add edge from a_i to b_j
            graph[i].append(j)

# Find perfect matching in bipartite graph
match_to = [-1] * n

# DFS to find augmenting path
def bpm(u, visited):
    for v in graph[u]:
        if not visited[v]:
            visited[v] = True
            if match_to[v] == -1 or bpm(match_to[v], visited):
                match_to[v] = u
                return True
    return False

# Find perfect matching
for i in range(n):
    if i not in graph:
        # No matching possible for this a_i, but problem says solution exists
        pass
    visited = [False] * n
    bpm(i, visited)

# Check if we have a perfect matching
if all(v != -1 for v in match_to):
    # Calculate minimum x
    x = 0
    for i, j in enumerate(match_to):
        x = max(x, (b[j] - a[i]) % m)
    print(x)
else:
    # Problem says solution exists, so this should never happen
    pass
