def solve():
    import sys
    input = sys.stdin.read().splitlines()
    idx = 0

    while idx < len(input):
        line = input[idx].strip()
        if not line:
            idx += 1
            continue

        n = int(line)
        if n == 0:
            break

        idx += 1

        tools = {}  # map from name to (day1, sup)

        for _ in range(n):
            if idx >= len(input):
                break

            parts = input[idx].strip().split()
            name = parts[0]
            day1 = int(parts[1])
            sup = parts[2]
            day2 = int(parts[3])

            tools[name] = (day1, sup)

            idx += 1

        # Build DAG where edge weight is (day1 - day2)
        dag = {name: [] for name in tools}
        for name in tools:
            day1, sup = tools[name]
            dag[sup].append((name, day1 - day2))

        # Build in-degree map
        in_degree = {name: 0 for name in dag}
        for sup in dag:
            for name, weight in dag[sup]:
                in_degree[name] += 1

        # Queue for nodes with in_degree 0
        queue = [name for name, deg in in_degree.items() if deg == 0]

        # Longest path distances
        dist = {name: 0 for name in dag}

        while queue:
            u = queue.pop(0)
            for v, weight in dag.get(u, []):
                dist[v] = max(dist[v], dist[u] + weight)
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    queue.append(v)

        # The longest path length
        longest_path = max(dist.values())

        # Total if all made from scratch
        total_day1 = sum(day1 for day1, _ in tools.values())

        # Minimum days = total_day1 - longest_path
        result = total_day1 - longest_path
        print(result)

if __name__ == "__main__":
    solve()
