def solve():
    t = int(input())

    for _ in range(t):
        n, k, l = map(int, input().split())
        d = list(map(int, input().split()))

        # Check if any position has depth > l
        for i in range(n):
            if d[i] > l:
                print("No")
                break

        # The pattern of depth changes: increase for k seconds, then decrease for k seconds
        # Period = 2k
        # p[t % 2k] = t if t < k, p[t % 2k] = 2k - t - 1 if t >= k

        # We can use BFS for each test case to find if there's a valid path
        from collections import deque

        # earliest_time[i] = earliest time we can be at position i
        earliest_time = [float('inf')] * (n + 2)
        earliest_time[0] = 0

        # Use BFS to find the earliest valid time for each position
        # Start from position 0 at time 0

        queue = deque([(0, 0)])  # (position, time)

        while queue:
            pos, t = queue.popleft()

            if pos == n + 1:
                # Reached island
                break

            # Try to swim to pos + 1
            if pos + 1 <= n:
                next_pos = pos + 1
                next_time = t + 1

                # Check if this time is valid for position next_pos
                depth = d[next_pos - 1]
                max_depth = l - depth
                period = 2 * k

                t_mod = next_time % period

                if t_mod < k:
                    if t_mod <= max_depth:
                        if earliest_time[next_pos] == float('inf'):
                            earliest_time[next_pos] = next_time
                            queue.append((next_pos, next_time))
                else:
                    if t_mod >= (2 * k - max_depth - 1):
                        if earliest_time[next_pos] == float('inf'):
                            earliest_time[next_pos] = next_time
                            queue.append((next_pos, next_time))

            # Try to stay at current position
