for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    n = int(line)

    if n == 0:
        break

    total_court_fee = 0

    for _ in range(n):
        line = sys.stdin.readline().strip()
        if not line:
            continue
        p, m = map(int, line.split())

        # Find primes in range [p-m, p+m]
        a = max(0, p - m)
        b = min(999983, p + m)
        count = count_primes_in_range(a, b)

        # Calculate court fees
        if count > 0:
            court_fee = count - 1
        else:
            court_fee = 1

        total_court_fee += court_fee

    print(total_court_fee)

