def solve():
    t = int(input())
    for _ in range(t):
        n, m = map(int, input().split())
        k = list(map(int, input().split()))
        c = list(map(int, input().split()))

        # For each friend, we can give them a present from 1 to k_i (1-indexed)
        # Since c is non-decreasing, we want to give them the cheapest available present

        # Sort friends by k_i in descending order
        friends = sorted([(ki, idx) for idx, ki in enumerate(k)], key=lambda x: -x[0])

        # Keep track of which presents we've used
        used = [False] * m

        cost = 0

        for ki, idx in friends:
            # Find the cheapest available present from 1 to ki (1-indexed)
            cheapest = -1
            for j in range(ki - 1):  # j from 0 to ki-1 (0-indexed)
                if not used[j]:
                    if cheapest == -1 or c[j] < c[cheapest]:
                        cheapest = j

            if cheapest != -1:
                used[cheapest] = True
                cost += c[cheapest]
            else:
                # No available presents, pay c_{ki}
                cost += c[ki - 1]

        print(cost)

solve()
