# We can optimize this further by only tracking the most recent operation for each row and column
# and then reconstructing the answer using those

row_color = [0] * (n + 1)
col_color = [0] * (m + 1)

for _ in range(k):
    parts = input().split()
    if parts[0] == '1':
        r = int(parts[1])
        a = int(parts[2])
        row_color[r] = a
    else:
        c = int(parts[1])
        a = int(parts[2])
        col_color[c] = a

# Reconstruct the result
result = []
for i in range(1, n + 1):
    row = []
    r_color = row_color[i]
    for j in range(1, m + 1):
        c_color = col_color[j]
        # The last operation to affect this cell
        # If both have been painted, the more recent one wins
        if row_color[i] != 0 and col_color[j] != 0:
            if row_color[i] > col_color[j]:
                row.append(str(r_color))
            else:
                row.append(str(c_color))
        elif row_color[i] != 0:
            row.append(str(r_color))
        elif col_color[j] != 0:
            row.append(str(c_color))
        else:
            row.append('0')
    result.append(' '.join(row) + ' ')

for line in result:
    print(line)
