import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    M = int(next(it))

    first_map = []
    for _ in range(N):
        first_map.append(next(it))

    second_map = []
    for _ in range(M):
        second_map.append(next(it))

    # Find i such that the M rows of first_map starting at i match
    # the M rows of second_map starting at some column j

    # Try all possible starting positions in first_map
    for i in range(N - M + 1):
        match = True
        # For each row in the M×M section
        for row_idx in range(M):
            first_row = first_map[i + row_idx]
            # Check if this row matches any row in the second map shifted by j
            for j in range(N - M + 1):
                second_row = second_map[row_idx][j:j+M]
                if first_row != second_row:
                    match = False
                    break
            if not match:
                break

        if match:
            # Found a match, i is 0-indexed, output i+1
            # j is 0-indexed, output j+1
            print(i + 1, j + 1)
            return

if __name__ == "__main__":
    main()
"}

