{"code": "import sys
from collections import deque

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    N = int(data[0])
    d = [int(data[i + 1]) for i in range(N)]

    # Build graph: edges from i to j
    # i -> j if 10*|i-j| <= d[i] (i.e., |i-j| <= d[i]//10)
    graph = [[] for _ in range(N)]
    for i in range(N):
        max_jump = d[i] // 10
        for j in range(i - max_jump, i + max_jump + 1):
            if 0 <= j < N and j != i:
                graph[i].append(j)

    # BFS from 0 to N-1
    def bfs(start, end):
        visited = [False] * N
        q = deque([start])
        visited[start] = True
        while q:
            u = q.popleft()
            if u == end:
                return True
            for v in graph[u]:
                if not visited[v]:
                    visited[v] = True
                    q.append(v)
        return False

    if bfs(0, N - 1) and bfs(N - 1, 0):
        print("yes")
    else:
        print("no")

if __name__ == "__main__":
