for _ in range(t):
    n, x = map(int, input().split())
    a = list(map(int, input().split()))
    a.sort()

    teams = 0
    left = 0

    while left < n:
        # How many programmers do we need to form a team starting at left?
        needed = x // a[left]
        if a[left] * needed >= x:
            # Check if we have enough programmers left
            if needed <= n - left:
                teams += 1
                left += needed
            else:
                break
        else:
            # We need one more programmer
            if left < n - 1:
                left += 1
            else:
                break

    print(teams)
