import sys

class FenwickTree:
    def __init__(self, n):
        self.n = n
        self.tree = [0] * (n + 1)

    def update(self, idx, delta):
        while idx <= self.n:
            self.tree[idx] += delta
            idx += idx & -idx

    def query(self, idx):
        res = 0
        while idx > 0:
            res += self.tree[idx]
            idx -= idx & -idx
        return res

    def find_kth(self, k):
        idx = 0
        sum_so_far = 0
        for b in range(self.n.bit_length(), 0, -1):
            mask = 1 << (b - 1)
            if idx + mask <= self.n:
                if sum_so_far + self.query(idx + mask) < k:
                    sum_so_far += self.query(idx + mask)
                    idx += mask
        return idx + 1

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    s = data[0]
    m = int(data[1])

    n = len(s)

    # Create BIT for each character 'a' to 'z'
    bit = [None] * 27  # bit[0] unused
    for i in range(1, 27):
        bit[i] = FenwickTree(n)

    # Initialize BITs
    for i in range(n):
        char = ord(s[i]) - ord('a') + 1  # 1-indexed
        bit[char].update(i + 1, 1)

    deleted = [False] * (n + 1)  # 1-indexed

    for i in range(2, 2 + 2 * m, 2):
        K = int(data[i])
        x = data[i + 1]
        char_idx = ord(x) - ord('a') + 1

        # Binary search on original indices to find K-th occurrence of char_idx
        # Actually, we can use bit[char_idx].find_kth(K) directly
        pos = bit[char_idx].find_kth(K)

        # Mark deleted and update BIT
        deleted[pos] = True
        bit[char_idx].update(pos, -1)

    # Rebuild result
    res = []
    for i in range(1, n + 1):
        if not deleted[i]:
            res.append(s[i - 1])

    print(''.join(res))

if __name__ == '__main__':
    main()
