def solve():
    MOD = 1000000007

    # Read input
    import sys
    data = sys.stdin.read().strip().split('\n')

    if not data:
        return

    N = int(data[0])
    S = set()
    idx = 1

    # Read N strings
    while idx < len(data) and len(S) < N:
        s = data[idx].strip()
        if s:
            S.add(s)
        idx += 1

    # Read target string t
    if idx < len(data):
        t = data[idx].strip()
    else:
        t = ''

    # Dynamic programming approach
    len_t = len(t)
    dp = [0] * (len_t + 1)
    dp[0] = 1

    # Precompute for each position which strings match
    match_pos = {}
    for pos in range(len_t):
        match_pos[pos] = []
        for s in S:
            s_len = len(s)
            if pos + s_len <= len_t and t[pos:pos+s_len] == s:
                match_pos[pos].append(s_len)

    # Fill dp
    for pos in range(len_t):
        for s_len in match_pos[pos]:
            dp[pos + s_len] = (dp[pos + s_len] + dp[pos]) % MOD

    print(dp[len_t])

if __name__ == '__main__':
    solve()
