            if pos + s_len <= len_t and t[pos:pos+s_len] == s:
                match_pos[pos].append(s_len)

    # Fill dp
    for pos in range(len_t):
        for s_len in match_pos[pos]:
            dp[pos + s_len] = (dp[pos + s_len] + dp[pos]) % MOD

    print(dp[len_t])

