def max_dollars(n, memo=None):
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]

    # Option 1: sell directly
    option1 = n

    # Option 2: exchange into n//2, n//3, n//4
    option2 = 0
    for val in [n // 2, n // 3, n // 4]:
        if val > 0:
            option2 += max_dollars(val, memo)

    result = max(option1, option2)
    memo[n] = result
    return result

