import sys

def lps(s):
    n = len(s)
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n, 0, -1):
        dp[i][i] = 1
    for i in range(n - 1, 0, -1):
        for j in range(i + 1, n + 1):
            if s[i - 1] == s[j - 1]:
                dp[i][j] = 2 + dp[i + 1][j - 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])
    return dp[1][n]

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    t = int(data[0])
    index = 1
    results = []
    for _ in range(t):
        n = int(data[index])
        s = data[index + 1]
        index += 2
        if len(s) != n:
            s = s[:n]
        l = lps(s)
        res = len(s) - l
        results.append(str(res))
    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
"}

