def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def gcd_three(a, b, c):
    return gcd(gcd(a, b), c)

T = int(input())
for _ in range(T):
    a, b, c = map(int, input().split())

    # Sort to easily find the largest
    nums = sorted([a, b, c])

    # Check Pythagorean condition
    if nums[0]**2 + nums[1]**2 != nums[2]**2:
        print("NO")
        continue

    # Check if all three are coprime
    if gcd_three(nums[0], nums[1], nums[2]) == 1:
        print("YES")
    else:
        print("NO")
