import sys

def count_trailing_zeros_in_factorial(n: int, m: int) -> int:
    """Count trailing zeros of m! in base n"""

    # Get prime factorization of n
    prime_factors = {}
    temp = n

    # Find prime factors
    for i in range(2, int(temp ** 0.5) + 1):
        while temp % i == 0:
            prime_factors[i] = prime_factors.get(i, 0) + 1
            temp //= i

    # If temp > 1, it's a prime factor
    if temp > 1:
        prime_factors[temp] = prime_factors.get(temp, 0) + 1

    # Count trailing zeros using Legendre's formula
    if not prime_factors:
        return 0

    max_zero = 0
    for p, e in prime_factors.items():
        # Count how many times p divides m!
        count_p = 0
        power = p
        while power <= m:
            count_p += m // power
            power *= p

        # Number of times p^e divides m! is floor(count_p / e)
        max_zero = min(max_zero, count_p // e)

    return max_zero

def parse_number(s: str, base: int) -> int:
    """Parse string number in given base to decimal"""
    num = 0
    for ch in s:
        if ch.isdigit():
            digit = int(ch)
        else:
            digit = ord(ch.upper()) - ord('A') + 10

        # Check if digit is valid
        if digit >= base:
            raise ValueError(f"Invalid digit {ch} in base {base}")

        num = num * base + digit
    return num

def main():
    input_lines = sys.stdin.read().strip().split('\n')

    for line in input_lines:
        line = line.strip()
        if not line:
            continue

        if line == '0 0':
            break

        # Parse N and M
        parts = line.split()
        if len(parts) != 2:
            continue

        try:
            n_str, m_str = parts
            n = int(n_str)
            if n == 0:
                break
        except ValueError:
            continue

        try:
            m = parse_number(m_str, n)
        except ValueError:
            continue

        # Compute trailing zeros
        trailing_zeros = count_trailing_zeros_in_factorial(n, m)
        print(trailing_zeros)

if __name__ == '__main__':
    main()
"}

