{"code": "
N, A, B = map(int, input().split())

if A > B:
    print(0)
else:
    if N == 1:
        print(1 if A == B else 0)
    else:
        # minimum sum = A*N + B (all but one are A)
        # maximum sum = A + B*N (all but one are B)
        min_sum = A * N + B
        max_sum = A + B * N
        ans = max_sum - min_sum + 1
        print(ans)
"}

