N, A, B = map(int, input().split())

if A > B:
    print(0)
else:
    if N == 1:
        print(1 if A == B else 0)
    else:
        # The remaining N-2 numbers each can be between A and B
        # minimum sum of remaining: (N-2)*A
        # maximum sum of remaining: (N-2)*B
        # total range: (N-2)*(B - A) + 1
        ans = (N - 2) * (B - A) + 1
        print(ans)
"}

