def count_trailing_zeros_in_factorial_base(n_str: str, m_str: str, base: int) -> int:
    """Count trailing zeros of m! in base n_str using Legendre's formula"""

    # Convert n_str to integer (we need to know its prime factorization)
    n = int(n_str)

    # Function to count prime factors of n
    def prime_factors(n: int) -> dict[int, int]:
        factors = {}
        # Check for 2 separately
        while n % 2 == 0:
            factors[2] = factors.get(2, 0) + 1
            n //= 2

        # Check for odd factors up to sqrt(n)
        i = 3
        while i * i <= n:
            while n % i == 0:
                factors[i] = factors.get(i, 0) + 1
                n //= i
            i += 2

        # If remaining n is > 1, it's a prime
        if n > 1:
            factors[n] = factors.get(n, 0) + 1

        return factors

    # Function to count how many times prime p divides m!
    def count_factor_in_factorial(p: int, m: int) -> int:
        count = 0
        power = p
        while power <= m:
            count += m // power
            power *= p
        return count

    # Convert m_str from base to decimal
    def base_to_decimal(s: str, base: int) -> int:
        n = 0
        for ch in s:
            if ch.isdigit():
                digit = int(ch)
            else:
                digit = ord(ch) - ord('A') + 10
            n = n * base + digit
        return n

    # Get prime factors of base
    factors = prime_factors(base)

    # Convert m_str to decimal
    m_decimal = base_to_decimal(m_str, base)

    # Calculate trailing zeros
    trailing_zeros = float('inf')
    for prime, exponent in factors.items():
        count = count_factor_in_factorial(prime, m_decimal)
        trailing_zeros = min(trailing_zeros, count // exponent)

    return trailing_zeros


def main():
    import sys

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        n_str, m_str = line.split()
        if n_str == '0' and m_str == '0':
            break

        result = count_trailing_zeros_in_factorial_base(n_str, m_str, int(n_str))
        print(result)

if __name__ == "__main__":
    main()
"}

