def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        n = int(next(it))
        freq = {}
        distinct = 0

        for _ in range(n):
            val = int(next(it))
            freq[val] = freq.get(val, 0) + 1
            distinct += 1 if val not in freq else 0

        if distinct == 1:
            # All values are the same, need to remove one at a time
            out_lines.append(str(n))
        else:
            # At least one element of each value, can pair elements
            out_lines.append(str((n + 1) // 2))  # ceil(n / 2)

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
