def is_good(sequence):
    """Check if a sequence is good"""
    n = len(sequence)
    if n == 0:
        return True

    # Find all powers of two up to 2^32 (since max a_i is 10^9, sum can be up to 2*10^9, so 2^31 is safe)
    powers = set()
    p = 1
    while p <= 2 * 10**9:
        powers.add(p)
        p *= 2

    # Create a frequency map
    freq = {}
    for num in sequence:
        freq[num] = freq.get(num, 0) + 1

    good = True
    for num in sequence:
        found = False
        for p in powers:
            complement = p - num
            if complement in freq:
                # Check if we can use this complement
                if complement == num:
                    # Need at least 2 elements of this value
                    if freq[num] >= 2:
                        found = True
                        break
                else:
                    # Need at least one element of this value
                    if freq[complement] >= 1:
                        found = True
                        break
        if not found:
            good = False
            break

    return good

