import heapq

def dijkstra(n, adj, start):
    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    heap = [(0, start)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        for v, w in adj[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                heapq.heappush(heap, (dist[v], v))
    return dist

T = int(input())
for _ in range(T):
    N, M = map(int, input().split())
    adj = [[] for _ in range(N + 1)]
    for _ in range(M):
        X, Y, C = map(int, input().split())
        adj[X].append((Y, C))
        adj[Y].append((X, C))
    S, A, H = map(int, input().split())

    s_dist = dijkstra(N, adj, S)
    a_dist = dijkstra(N, adj, A)
    h_dist = dijkstra(N, adj, H)

    max_time = 0
    for v in range(1, N + 1):
        if v == S or v == A or v == H:
            continue
        total = s_dist[v] + 2 * a_dist[v] + h_dist[v]
        if total > max_time:
            max_time = total

    print(max_time)
"}

