import math
import sys


def solve():
    for line in sys.stdin:
        if not line.strip():
            continue

        D, E = map(int, line.strip().split())

        if D == 0 and E == 0:
            break

        min_diff = float('inf')

        for x in range(D + 1):
            y = D - x
            distance = math.sqrt(x * x + y * y)
            diff = abs(distance - E)

            if diff < min_diff:
                min_diff = diff

        print(f"{min_diff:.10f}")

if __name__ == "__main__":
    solve()
"}

