def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    q = int(next(it))

    a = [0] * n
    for i in range(n):
        a[i] = int(next(it))

    k = [0] * q
    for i in range(q):
        k[i] = int(next(it))

    # Compute prefix sums
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + a[i]

    total_arrows = 0

    for ki in k:
        total_arrows += ki

        if total_arrows >= prefix[n]:
            # All warriors die, then revive
            print(n)
        else:
            # Binary search for the number of dead warriors
            low = 0
            high = n
            dead = 0

            while low < high:
                mid = (low + high) // 2
                if prefix[mid] <= total_arrows:
                    dead = mid
                    low = mid + 1
                else:
                    high = mid

            standing = n - dead
            print(standing)

