    k = [0] * q
    for i in range(q):
        k[i] = int(next(it))

    # Compute prefix sums
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + a[i]

    total_arrows = 0

    for ki in k:
        total_arrows += ki

        if total_arrows >= prefix[n]:
            # All warriors die, then revive
            print(n)
