import sys

def solve():
    S = int(sys.stdin.read().strip())

    # Try to find a simple triangle with vertices (0,0), (a,0), (0,b) where a*b = S
    # This gives area (1/2)*a*b = S/2 as needed
    # We need to find factors a and b such that both are ≤ 10^9

    # Use a brute force approach for finding factors
    for a in range(1, int(S**0.5) + 1):
        if S % a == 0:
            b = S // a
            if b <= 10**9:
                print(f"0 0 {a} 0 0 {b}")
                return
            elif a <= 10**9:
                print(f"0 0 {b} 0 0 {a}")
                return

    # If we can't find such a simple triangle, use a different configuration
    # For large S, we can use vertices (0,0), (1,0), (0,S) but we need S ≤ 10^9
    # So this only works for S ≤ 10^9

    if S <= 10**9:
        print(f"0 0 1 0 0 {S}")
    else:
        # For S > 10^9, we need a different approach
        # Let's use vertices (S,0), (0,0), (0,1) - area = S/2
        print(f"0 0 {S} 0 0 1")

if __name__ == "__main__":
    solve()
