def solve():
    n = int(input())
    s = list(input().strip())

    # If already all same color
    if all(c == 'W' for c in s):
        print(0)
        return
    if all(c == 'B' for c in s):
        print(0)
        return

    ops = []
    # Try to make all white
    for i in range(n - 1):
        if s[i] == 'B':
            # Flip the pair to change this black block to white
            ops.append(i + 1)
            s[i] = 'W'
            s[i+1] = 'B'  # Flip the next block

    # Try to make all black (if making white failed)
    if not ops or any(c == 'W' for c in s):
        ops = []
        for i in range(n - 1):
            if s[i] == 'W':
                # Flip the pair to change this white block to black
