import sys

def solve():
    T = int(sys.stdin.readline())

    results = []

    for _ in range(T):
        # Read N
        line = sys.stdin.readline()
        while line.strip() == '':
            line = sys.stdin.readline()
        N = int(line.strip())

        # Read array
        arr_line = sys.stdin.readline()
        while arr_line.strip() == '':
            arr_line = sys.stdin.readline()
        arr = list(map(int, arr_line.strip().split()))

        # Count distinct elements
        distinct_count = 0
        seen = set()
        for num in arr:
            if num not in seen:
                seen.add(num)
                distinct_count += 1

        if distinct_count == 1:
            results.append(str(N))
        else:
            results.append(str((N + 1) // 2))

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
"}

