def solve():
    t = int(input())
    for _ in range(t):
        n, x = map(int, input().split())
        a = list(map(int, input().split()))
        a.sort()

        teams = 0
        i = 0  # start of remaining programmers

        while i + 1 <= n:
            # Try to form a team starting at i
            # Try team sizes from largest to smallest
            for k in range(1, n - i + 1 + 1):
                # k can be from 1 to n-i
                # Actually range is 1 to n-i, so we use range(1, n - i + 1)
                required_skill = (x + k - 1) // k
                if a[i] >= required_skill:
                    teams += 1
                    i += k
                    break
            else:
                break

        print(teams)

if __name__ == "__main__":
    solve()
