def min_insertions_to_palindrome(s):
    n = len(s)
    # dp[i][j] = minimum insertions to make s[i..j] a palindrome
    dp = [[0] * n for _ in range(n)]

    # Base case: i == j means single character, already palindrome
    for i in range(n):
        dp[i][i] = 0

    # Fill dp table
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if s[i] == s[j]:
                dp[i][j] = dp[i + 1][j - 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1]) + 1

    return dp[0][n - 1]

