def min_insertions(s):
    # Check if already a palindrome
    if is_palindrome(s):
        return 0

    n = len(s)
    # Try inserting one character at each position
    for i in range(n + 1):
        # Try inserting the first character at position i
        if i == 0 and s[0] == s[-1]:
            continue  # Skip if first and last characters are already equal
        new_str = s[:i] + s[0] + s[i:]
        if is_palindrome(new_str):
            return 1

        # Try inserting the last character at position i
        if i == n and s[0] == s[-1]:
            continue
        new_str = s[:i] + s[-1] + s[i:]
        if is_palindrome(new_str):
            return 1

    # If no palindrome found with one insertion, try two?
    return 2

