    for L in range(n, 0, -1):
        for i in range(max(0, L - n), min(n, L) + 1):
            j = L - i
            if i == 0:
                # prefix is empty, suffix of length L
                suffix = s[-L:] if L <= n else ''
                if is_palindrome(suffix):
