import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    k = int(next(it))
    t = int(next(it))

    waste_set = set()

    for _ in range(k):
        a = int(next(it))
        b = int(next(it))
        waste_set.add((a, b))

    for _ in range(t):
        i = int(next(it))
        j = int(next(it))

        if (i, j) in waste_set:
            print("Waste")
            continue

        # Count cultivated cells before (i, j)
        cultivated_before = 0

        # Count cells in rows 1 to i-1
        for row in range(1, i):
            for col in range(1, m + 1):
                if (row, col) not in waste_set:
                    cultivated_before += 1

        # Count cells in row i, columns 1 to j-1
        for col in range(1, j):
            if (i, col) not in waste_set:
                cultivated_before += 1

        if cultivated_before % 3 == 0:
            print("Carrots")
        elif cultivated_before % 3 == 1:
            print("Kiwis")
        else:
            print("Grapes")

solve()
"}

